function createHelloWorld(): (...args: unknown[]) => string {
  return (..._args: unknown[]) => "Hello World";
}

function helloForEachCall(calls: unknown[][]): string[] {
  const greet = createHelloWorld();
  return calls.map(args => greet(...args));
}

