def create_hello_world():
    def greet(*args, **kwargs):
        return "Hello World"
    return greet


class Solution:
    def helloForEachCall(self, calls: List[list]) -> List[str]:
        greet = create_hello_world()
        return [greet(*args) for args in calls]

